"use client";

import { FormEvent, useMemo, useState } from "react";

interface Book {
  id: string;
  title: string;
  author: string;
  read: boolean;
}

export default function ReadingListPage() {
  const [books, setBooks] = useState<Book[]>([]);
  const [title, setTitle] = useState("");
  const [author, setAuthor] = useState("");

  const unread = useMemo(() => books.filter((b) => !b.read).length, [books]);

  function addBook(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (!title.trim()) return;
    setBooks((prev) => [...prev, { id: crypto.randomUUID(), title: title.trim(), author: author.trim(), read: false }]);
    setTitle("");
    setAuthor("");
  }

  function toggle(id: string) {
    setBooks((prev) => prev.map((b) => (b.id === id ? { ...b, read: !b.read } : b)));
  }

  return (
    <main style={{ maxWidth: 480, margin: "2rem auto", fontFamily: "Georgia, serif" }}>
      <h1>Reading list</h1>
      <p>{unread === 0 ? "Nothing left to read." : `${unread} book${unread === 1 ? "" : "s"} still unread`}</p>
      <form onSubmit={addBook} style={{ display: "grid", gap: 8, marginBottom: 16 }}>
        <input placeholder="Title" value={title} onChange={(e) => setTitle(e.target.value)} required />
        <input placeholder="Author" value={author} onChange={(e) => setAuthor(e.target.value)} />
        <button type="submit">Add book</button>
      </form>
      <ul style={{ listStyle: "none", padding: 0 }}>
        {books.map((book) => (
          <li key={book.id} style={{ padding: "6px 0", borderBottom: "1px solid #ddd" }}>
            <label>
              <input type="checkbox" checked={book.read} onChange={() => toggle(book.id)} />{" "}
              <span style={{ textDecoration: book.read ? "line-through" : "none" }}>
                {book.title}
                {book.author && <em> by {book.author}</em>}
              </span>
            </label>
          </li>
        ))}
      </ul>
    </main>
  );
}
